const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1000 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  console.log('loaded title:', await page.title());
  console.log('team options:', await page.locator('#home-team option').count());
  await page.locator('#squad-toggle').click();
  console.log('women squad toggle:', await page.locator('#mode-home').textContent(), await page.locator('#squad-toggle').getAttribute('aria-pressed'));
  await page.locator('#squad-toggle').click();
  await page.locator('#start-game').click();
  console.log('after start:', await page.evaluate(() => `${match.phase}; ${document.querySelector('#control-title').textContent}`));
  await page.locator('#start-game').click();
  await page.waitForSelector('[data-shot="drive"]', { timeout: 3000 });
  console.log('shot phase:', await page.evaluate(() => match.phase));
  await page.locator('[data-shot="drive"]').click();
  await page.waitForFunction(() => match.phase === 'ready', null, { timeout: 3000 });
  console.log('ball result:', await page.locator('#overs').textContent(), await page.locator('#score').textContent());
  await page.evaluate(() => { match.firstBalls = 119; });
  await page.locator('#start-game').click();
  await page.waitForSelector('[data-shot="drive"]', { timeout: 3000 });
  await page.locator('[data-shot="drive"]').click();
  await page.waitForFunction(() => match.phase === 'inningsEnd', null, { timeout: 3000 });
  console.log('first innings transition:', await page.locator('#innings-label').textContent(), await page.locator('#next-innings').isVisible());
  await page.locator('#next-innings').click();
  console.log('second innings:', await page.evaluate(() => `${match.innings}; ${match.phase}; ${match.second}`));
  await page.evaluate(() => { match.secondBalls = 119; });
  await page.locator('#start-game').click();
  await page.waitForSelector('[data-shot="drive"]', { timeout: 3000 });
  await page.locator('[data-shot="drive"]').click();
  await page.waitForFunction(() => match.phase === 'finished', null, { timeout: 3000 });
  console.log('match result:', await page.locator('#control-hint').textContent());
  await page.locator('text=PLAY AGAIN').click();
  console.log('reset:', await page.locator('#match-status').textContent(), await page.locator('#overs').textContent());
  await page.screenshot({ path: '/tmp/opencode/backyard-test.jpg', type: 'jpeg', quality: 78, fullPage: true });
  console.log('screenshot:', await page.evaluate(() => ({ width: document.documentElement.scrollWidth, height: document.documentElement.scrollHeight })));
  console.log('page errors:', errors.length ? errors.join(' | ') : 'none');
  await browser.close();
  if (errors.length) process.exitCode = 1;
})().catch(e => { console.error(e); process.exitCode = 1; });

