.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 284px;gap:24px;margin-top:22px}
.scoreboard{background:#214336;color:#f6ecd4;border:7px solid #b67a46;border-radius:3px;outline:1px solid #805632;box-shadow:0 4px 11px #262c241f,inset 0 0 0 1px #e4b780;position:relative;padding:13px 16px 0;min-height:228px;background-image:repeating-linear-gradient(0deg,#ffffff03 0,#ffffff03 1px,transparent 1px,transparent 4px)}
.scoreboard-top{display:flex;justify-content:space-between;align-items:start;color:#e3c991;font:9px var(--mono);line-height:1.45;letter-spacing:1px}
.scoreboard-name{text-align:center;color:#fff4db;font:700 12px var(--serif);letter-spacing:1.1px;margin:7px 0 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.score-display{display:flex;align-items:center;justify-content:center;height:73px;gap:6px;font:500 56px/.9 var(--mono);letter-spacing:-5px;color:#f2e7cb;text-shadow:0 2px 1px #fff3,inset 0 2px 1px #1c3328}
.score-meta{display:flex;justify-content:space-between;padding:0 35px;color:#d2c49f;font:8px var(--mono);letter-spacing:1px;margin-top:-3px}
.overs-row{display:flex;justify-content:space-between;padding:0 4px 9px}
.scoreboard-bottom{margin:0 -16px;background:#17362a;border-top:1px solid #d9c79b33;padding:7px 15px;display:flex;justify-content:space-between;color:#dbc998;font:9px var(--mono);letter-spacing:.65px}
.score-column{display:flex;flex-direction:column;gap:11px}

