 await page.addInitScript(()=>{
  window.__oscillators=0;
  const Original=window.AudioContext||window.webkitAudioContext;
  if(Original){ const proto=Original.prototype; const original=proto.createOscillator; proto.createOscillator=function(){window.__oscillators++;return original.call(this)}; }
 });
 await page.goto('http://localhost:3002');
 await page.locator('#sound-toggle').click();
 await page.waitForTimeout(100);
 const on=await page.evaluate(()=>({pressed:document.querySelector('#sound-toggle').getAttribute('aria-pressed'),label:document.querySelector('.sound-label').textContent,oscillators:window.__oscillators,context:window.audio?.state||'not-global'}));
 await page.locator('#sound-toggle').click();
